/**
 * @method
 * @name cex#fetchCurrencies
 * @description fetches all available currencies on an exchange
 * @see https://trade.cex.io/docs/#rest-public-api-calls-currencies-info
 * @param {dict} [params] extra parameters specific to the exchange API endpoint
 * @returns {dict} an associative dictionary of currencies
 */
func (this *Cex) FetchCurrenciesAsync(optionalArgs ...any) <-chan AsyncResult[map[string]any] {
	ch := make(chan AsyncResult[map[string]any], 1)
	go this.fetchCurrenciesBody(ch, optionalArgs...)
	return ch
}
func (this *Cex) fetchCurrenciesBody(ch chan AsyncResult[map[string]any], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var promises []any = []any{}
	promises = append(promises, this.PublicPostGetCurrenciesInfo(params))
	//
	//    {
	//        "ok": "ok",
	//        "data": [
	//            {
	//                "currency": "ZAP",
	//                "fiat": false,
	//                "precision": "8",
	//                "walletPrecision": "6",
	//                "walletDeposit": true,
	//                "walletWithdrawal": true
	//            },
	//            ...
	//
	promises = append(promises, this.PublicPostGetProcessingInfo(params))
	//
	//    {
	//        "ok": "ok",
	//        "data": {
	//            "ADA": {
	//                "name": "Cardano",
	//                "blockchains": {
	//                    "cardano": {
	//                        "type": "coin",
	//                        "deposit": "enabled",
	//                        "minDeposit": "1",
	//                        "withdrawal": "enabled",
	//                        "minWithdrawal": "5",
	//                        "withdrawalFee": "1",
	//                        "withdrawalFeePercent": "0",
	//                        "depositConfirmations": "15"
	//                    }
	//                }
	//            },
	//            ...
	//

	r := <-promiseAll(promises)
	if r.Err != nil {
		panic(r.Err)
	}
	var responses []any = ListTyped(r.Value)
	var dataCurrencies []any = SafeListTyped(responses[0], "data")
	var dataNetworks map[string]any = this.SafeDictMap(responses[1], "data", map[string]any{})
	var currenciesIndexed map[string]any = this.IndexBy(dataCurrencies, "currency")
	var data map[string]any = this.DeepExtend(currenciesIndexed, dataNetworks)

	ch <- AsyncResult[map[string]any]{Value: this.ParseCurrencies(this.ToArray(data))}
	return nil
}
func (this *Cex) ParseCurrency(rawCurrency any) map[string]any {
	var id *string = this.SafeString(rawCurrency, "currency")
	var code *string = this.SafeCurrencyCode(id)
	var isFiat *bool = this.SafeBool(rawCurrency, "fiat", false)
	var typeVar string = "crypto"
	if isFiat != nil && *isFiat {
		typeVar = "fiat"
	}
	var currencyPrecision *float64 = this.ParseNumber(this.ParsePrecision(this.SafeString(rawCurrency, "precision")))
	var networks map[string]any = map[string]any{}
	var rawNetworks map[string]any = SafeMapTyped(rawCurrency, "blockchains")
	var keys []string = nil
	if rawNetworks != nil {
		keys = make([]string, 0, len(rawNetworks))
		for objectKey := range rawNetworks {
			keys = append(keys, objectKey)
		}
	}
	for j := 0; j < len(keys); j++ {
		var networkId string = keys[j]
		var rawNetwork map[string]any = SafeMapTyped(rawNetworks, networkId)
		var networkCode *string = this.NetworkIdToCode(networkId, code)
		var deposit bool = (this.SafeString(rawNetwork, "deposit") != nil && *this.SafeString(rawNetwork, "deposit") == "enabled")
		var withdraw bool = (this.SafeString(rawNetwork, "withdrawal") != nil && *this.SafeString(rawNetwork, "withdrawal") == "enabled")
		if networkCode != nil {
			networks[*networkCode] = map[string]any{
				"id":        networkId,
				"network":   networkCode,
				"margin":    nil,
				"deposit":   deposit,
				"withdraw":  withdraw,
				"active":    nil,
				"fee":       this.SafeNumber(rawNetwork, "withdrawalFee"),
				"precision": currencyPrecision,
				"limits": map[string]any{
					"deposit": map[string]any{
						"min": this.SafeNumber(rawNetwork, "minDeposit"),
						"max": nil,
					},
					"withdraw": map[string]any{
						"min": this.SafeNumber(rawNetwork, "minWithdrawal"),
						"max": nil,
					},
				},
				"info": rawNetwork,
			}
		}
	}
	return this.SafeCurrencyStructure(map[string]any{
		"id":        id,
		"code":      code,
		"name":      nil,
		"type":      typeVar,
		"active":    nil,
		"deposit":   this.SafeBool(rawCurrency, "walletDeposit"),
		"withdraw":  this.SafeBool(rawCurrency, "walletWithdrawal"),
		"fee":       nil,
		"precision": currencyPrecision,
		"limits": map[string]any{
			"amount": map[string]any{
				"min": nil,
				"max": nil,
			},
			"withdraw": map[string]any{
				"min": nil,
				"max": nil,
			},
		},
		"networks": networks,
		"info":     rawCurrency,
	})
}

