func (this *Cex) ParseOrder(order any, optionalArgs ...any) Order {
	//
	//                "orderId": "1313003",
	//                "clientOrderId": "037F0AFEB93A",
	//                "clientId": "up421412345",
	//                "accountId": null,
	//                "status": "FILLED",
	//                "statusIsFinal": true,
	//                "currency1": "AI",
	//                "currency2": "USDT",
	//                "side": "BUY",
	//                "orderType": "Market",
	//                "timeInForce": "IOC",
	//                "comment": null,
	//                "rejectCode": null,
	//                "rejectReason": null,
	//                "initialOnHoldAmountCcy1": null,
	//                "initialOnHoldAmountCcy2": "10.23456700",
	//                "executedAmountCcy1": "25.606429",
	//                "executedAmountCcy2": "10.20904439",
	//                "requestedAmountCcy1": null,
	//                "requestedAmountCcy2": "10.20904439",
	//                "originalAmountCcy2": "10.23456700",
	//                "feeAmount": "0.02552261",
	//                "feeCurrency": "USDT",
	//                "price": null,
	//                "averagePrice": "0.3986",
	//                "clientCreateTimestamp": "1728474625320",
	//                "serverCreateTimestamp": "1728474624956",
	//                "lastUpdateTimestamp": "1728474628015",
	//                "expireTime": null,
	//                "effectiveTime": null
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var currency1 *string = this.SafeString(order, "currency1")
	var currency2 *string = this.SafeString(order, "currency2")
	var marketId any = nil
	if (currency1 != nil) && (currency2 != nil) {
		marketId = *currency1 + "-" + *currency2
	}
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	var symbol *string = SafeStringPtr(marketResolved["symbol"])
	var status *string = this.ParseOrderStatus(this.SafeString(order, "status"))
	var fee map[string]any = map[string]any{}
	var feeAmount *float64 = this.SafeNumber(order, "feeAmount")
	if feeAmount != nil {
		var currencyId *string = this.SafeString(order, "feeCurrency")
		var feeCode *string = this.SafeCurrencyCode(currencyId)
		fee["currency"] = feeCode
		fee["cost"] = feeAmount
	}
	var timestamp *int64 = this.SafeInteger(order, "serverCreateTimestamp")
	var requestedBase *float64 = this.SafeNumber(order, "requestedAmountCcy1")
	var executedBase *float64 = this.SafeNumber(order, "executedAmountCcy1")
	// const requestedQuote = this.safeNumber (order, 'requestedAmountCcy2');
	var executedQuote *float64 = this.SafeNumber(order, "executedAmountCcy2")
	return this.SafeOrder(map[string]any{
		"id":                  this.SafeString(order, "orderId"),
		"clientOrderId":       this.SafeString(order, "clientOrderId"),
		"timestamp":           timestamp,
		"datetime":            this.Iso8601(timestamp),
		"lastUpdateTimestamp": this.SafeInteger(order, "lastUpdateTimestamp"),
		"lastTradeTimestamp":  nil,
		"symbol":              symbol,
		"type":                this.SafeStringLower(order, "orderType"),
		"timeInForce":         this.SafeString(order, "timeInForce"),
		"postOnly":            nil,
		"side":                this.SafeStringLower(order, "side"),
		"price":               this.SafeNumber(order, "price"),
		"triggerPrice":        this.SafeNumber(order, "stopPrice"),
		"amount":              requestedBase,
		"cost":                executedQuote,
		"average":             this.SafeNumber(order, "averagePrice"),
		"filled":              executedBase,
		"remaining":           nil,
		"status":              status,
		"fee":                 fee,
		"trades":              nil,
		"info":                order,
	}, marketResolved)
}

