func (this *Cex) fetchLedgerBody(ch chan AsyncResult[[]LedgerEntry], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var code *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = code
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var currency map[string]any = nil
	var request map[string]any = map[string]any{}
	if code != nil {
		currency = this.Currency(code)
		request["currency"] = currency["id"]
	}
	if since != nil {
		request["dateFrom"] = since
	}
	if limit != nil {
		request["pageSize"] = limit
	}
	var until *int64 = nil
	until, paramsUntil := this.HandleParamInteger2(params, "until", "till")
	if until != nil {
		request["dateTo"] = *until
	}

	r1 := <-this.PrivatePostGetMyTransactionHistory(this.Extend(request, paramsUntil))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	//
	//    {
	//        "ok": "ok",
	//        "data": [
	//            {
	//                "transactionId": "30367722",
	//                "timestamp": "2024-10-14T14:08:49.987Z",
	//                "accountId": "",
	//                "type": "withdraw",
	//                "amount": "-12.39060600",
	//                "details": "Withdraw fundingId=1235039 clientId=up421412345 walletTxId=76337154166",
	//                "currency": "USDT"
	//            },
	//            ...
	//
	var data []any = SafeListTypedDefault(response, "data", []any{})

	ch <- AsyncResult[[]LedgerEntry]{Value: LedgerEntriesFromList(this.ParseLedger(data, currency, since, limit))}
	return nil
}
func (this *Cex) ParseLedgerEntry(item any, optionalArgs ...any) LedgerEntry {
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var amount *string = this.SafeString(item, "amount")
	var direction string
	if Precise.StringLe(amount, "0") {
		direction = "out"
		amount = Precise.StringMul("-1", amount)
	} else {
		direction = "in"
	}
	var currencyId *string = this.SafeString(item, "currency")
	var currencyResolved map[string]any = this.SafeCurrency(currencyId, currency)
	var code *string = this.SafeCurrencyCode(currencyId, currencyResolved)
	var timestampString *string = this.SafeString(item, "timestamp")
	var timestamp *int64 = this.Parse8601(timestampString)
	var typeVar *string = this.SafeString(item, "type")
	return this.SafeLedgerEntry(map[string]any{
		"info":             item,
		"id":               this.SafeString(item, "transactionId"),
		"direction":        direction,
		"account":          this.SafeString(item, "accountId", ""),
		"referenceAccount": nil,
		"referenceId":      nil,
		"type":             this.ParseLedgerEntryType(typeVar),
		"currency":         code,
		"amount":           this.ParseNumber(amount),
		"timestamp":        timestamp,
		"datetime":         this.Iso8601(timestamp),
		"before":           nil,
		"after":            nil,
		"status":           nil,
		"fee":              nil,
	}, currencyResolved)
}
func (this *Cex) ParseLedgerEntryType(typeVar *string) *string {
	var ledgerType map[string]any = map[string]any{
		"deposit":    "deposit",
		"withdraw":   "withdrawal",
		"commission": "fee",
	}
	return this.SafeString(ledgerType, typeVar, typeVar)
}

