func (this *Cex) Sign(path string, optionalArgs ...any) map[string]any {
	var api []string = GetArgStringSlice(optionalArgs, 0, []string{"public"})
	_ = api
	var method string = GetArgString(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	var apiName string = api[0]
	var apiUrl *string = this.SafeString(this.Urls["api"], apiName)
	if apiUrl == nil {
		panic(ExchangeError(this.Id + " sign() has no API URL for this endpoint"))
	}
	var url string = *apiUrl + "/" + this.ImplodeParams(path, params)
	var query any = this.Omit(params, this.ExtractParams(path))
	if apiName == "public" {
		if method == "GET" {
			if queryMap, _ := query.(map[string]any); len(queryMap) > 0 {
				url += "?" + this.Urlencode(query)
			}
		} else {
			var bodyJson string = this.Json(query)
			var headersJson map[string]any = map[string]any{
				"Content-Type": "application/json",
			}
			return map[string]any{
				"url":     url,
				"method":  method,
				"body":    bodyJson,
				"headers": headersJson,
			}
		}
	} else {
		this.CheckRequiredCredentials()
		var seconds string = strconv.FormatInt(this.Seconds(), 10)
		var bodySigned string = this.Json(query)
		var auth string = path + seconds + bodySigned
		var signature string = this.Hmac(this.Encode(auth), this.Encode(this.Secret), sha256, "base64")
		var headersSigned map[string]any = map[string]any{
			"Content-Type":     "application/json",
			"X-AGGR-KEY":       this.ApiKey,
			"X-AGGR-TIMESTAMP": seconds,
			"X-AGGR-SIGNATURE": signature,
		}
		return map[string]any{
			"url":     url,
			"method":  method,
			"body":    bodySigned,
			"headers": headersSigned,
		}
	}
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    nil,
		"headers": nil,
	}
}
func (this *Cex) HandleErrors(code int64, reason string, url string, method string, headers any, body string, response any, requestHeaders any, requestBody any) any {
	// in some cases, like from createOrder, exchange returns nested escaped JSON string:
	//      {"ok":"ok","data":{"messageType":"executionReport", "orderRejectReason":"{\"code\":405}"} }
	// and because of `.parseJson` bug, we need extra fix
	var responseFixed any = nil
	if response == nil {
		if false {
			panic(NullResponse(this.Id + " returned empty response"))
		} else if strings.HasPrefix(body, "{") {
			var fixed string = this.FixStringifiedJsonMembers(body)
			responseFixed = this.ParseJson(fixed)
		} else {
			panic(NullResponse(this.Id + " returned unparsed response: " + body))
		}
	}
	var responseParsed any = func() any {
		if response == nil {
			return responseFixed
		}
		return response
	}()
	var error *string = this.SafeString(responseParsed, "error")
	if error != nil {
		var feedback string = this.Id + " " + body
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], error, feedback)
		this.ThrowBroadlyMatchedException(this.Exceptions["broad"], error, feedback)
		panic(ExchangeError(feedback))
	}
	// check errors in order-engine (the responses are not standard, so we parse here)
	if strings.Index(url, "do_my_new_order") >= 0 {
		var data map[string]any = SafeMapTyped(responseParsed, "data")
		var rejectReason *string = this.SafeString(data, "rejectReason")
		if rejectReason != nil {
			this.ThrowBroadlyMatchedException(this.Exceptions["broad"], rejectReason, rejectReason)
			panic(ExchangeError(this.Id + " createOrder() " + *rejectReason))
		}
	}
	return nil
}

func NewCex(userConfig map[string]any) *Cex {
	p := newCex()
	p.Init(userConfig)
	return p
}

func (this *Cex) Init(userConfig map[string]any) {
	this.Exchange = Exchange{}
	this.Exchange.DerivedExchange = this
	this.Exchange.InitParent(userConfig, this.Describe(), this)
}

